import{_ as a,a as s,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"第一册：英语初阶 · 单元 6 复习与自测 · 第142–144课","description":"L121–L144 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 6 复习与自测 · 第142–144课","description":"L121–L144 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-06/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 6 复习与自测","summary":"L121–L144 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 6 复习与自测 · 第135–141课","link":"/life/english/new-concept/book-1/unit-06/review-part-03"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 6 复习与自测 · 第135–141课","link":"/life/english/new-concept/book-1/unit-06/review-part-03"},"next":false},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/review-part-04.md","filePath":"life/english/new-concept/book-1/unit-06/review-part-04.md"}'),l={name:"life/english/new-concept/book-1/unit-06/review-part-04.md"};function i(r,e,o,p,h,c){return s(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="第一册-英语初阶-·-单元-6-复习与自测-·-第142–144课" tabindex="-1">第一册：英语初阶 · 单元 6 复习与自测 · 第142–144课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-6-复习与自测-·-第142–144课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 6 复习与自测 · 第142–144课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-06/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-06/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-142-·-一般过去时被动语态" tabindex="-1">Lesson 142 · 一般过去时被动语态 <a class="header-anchor" href="#lesson-142-·-一般过去时被动语态" aria-label="Permalink to &quot;Lesson 142 · 一般过去时被动语态 {#lesson-142-·-一般过去时被动语态}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This bridge was built fifty years ago.</p><h3 id="练习-1-21" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-21" aria-label="Permalink to &quot;练习 1 {#练习-1-21}&quot;">​</a></h3><p>填分词：The bridge was ___ (build) in 1970.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> built</p><p><strong>解析：</strong> 按本课规则判断：被动语态由 be + 过去分词构成，时态与主谓一致体现在 be 上。一般过去时用 was/were + 分词。只有及物动词及可接受的及物结构通常能转被动，happen 不可机械写 was happened。执行者不重要或未知时，可以省略引出执行者的 by 短语；如 by the host 中 the host 是执行者。by 也可表示方式，如本课 by email 表示通过电子邮件，不能把所有 by 短语都理解为执行者。</p></details><p><strong>表达迁移：</strong> 围绕“把注意力从执行者转向事件对象”写两至三句，再读给同伴听。至少使用一次一般过去时被动语态，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This bridge was built fifty years ago. The guests were invited by email.</p><p>This bridge 为动作承受者，was built 为单数过去被动；fifty years ago 为明确过去时间。 The guests 为被邀请者，were invited 为过去被动；by email 表通过邮件这一方式，并非动作执行者。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-142">回看本课</a></p><h2 id="lesson-143-·-现在完成时与将来时被动" tabindex="-1">Lesson 143 · 现在完成时与将来时被动 <a class="header-anchor" href="#lesson-143-·-现在完成时与将来时被动" aria-label="Permalink to &quot;Lesson 143 · 现在完成时与将来时被动 {#lesson-143-·-现在完成时与将来时被动}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The path has been cleared of fallen branches.</p><h3 id="练习-1-22" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-22" aria-label="Permalink to &quot;练习 1 {#练习-1-22}&quot;">​</a></h3><p>补 be 的形式：The path has ___ cleared.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 按本课规则判断：现在完成时被动为 have/has been + 过去分词，将来时被动为 will be + 过去分词。have/has 仍要与主语一致，been 不可漏；will 后用原形 be，不用 been。先判断是否被动，再判断完成或将来，不能把两种结构拼成 will been。表达“树木已被种下”与“明天将被种下”时，动作对象相同而时间不同。</p></details><p><strong>表达迁移：</strong> 围绕“描述环境变化与待完成的工作”写两至三句，再读给同伴听。至少使用一次现在完成时与将来时被动，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The path has been cleared of fallen branches. New trees will be planted beside the stream.</p><p>The path 是清理对象，has been cleared 为现在完成时被动；of fallen branches 说明被清除的东西。 New trees 是被种植对象，will be planted 为将来时被动；beside the stream 表未来种植位置。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-143">回看本课</a></p><h2 id="lesson-144-·-现在完成时与将来时被动" tabindex="-1">Lesson 144 · 现在完成时与将来时被动 <a class="header-anchor" href="#lesson-144-·-现在完成时与将来时被动" aria-label="Permalink to &quot;Lesson 144 · 现在完成时与将来时被动 {#lesson-144-·-现在完成时与将来时被动}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> New trees will be planted beside the stream.</p><h3 id="练习-1-23" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-23" aria-label="Permalink to &quot;练习 1 {#练习-1-23}&quot;">​</a></h3><p>补 be 的形式：Trees will ___ planted.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> be</p><p><strong>解析：</strong> 按本课规则判断：现在完成时被动为 have/has been + 过去分词，将来时被动为 will be + 过去分词。have/has 仍要与主语一致，been 不可漏；will 后用原形 be，不用 been。先判断是否被动，再判断完成或将来，不能把两种结构拼成 will been。表达“树木已被种下”与“明天将被种下”时，动作对象相同而时间不同。</p></details><p><strong>表达迁移：</strong> 围绕“描述环境变化与待完成的工作”写两至三句，再读给同伴听。至少使用一次现在完成时与将来时被动，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>New trees will be planted beside the stream. The path has been cleared of fallen branches.</p><p>New trees 是被种植对象，will be planted 为将来时被动；beside the stream 表未来种植位置。 The path 是清理对象，has been cleared 为现在完成时被动；of fallen branches 说明被清除的东西。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-144">回看本课</a></p>',28)])])}const g=a(l,[["render",i]]);export{b as __pageData,g as default};
